};
List<Topic> get courseTopics => [...starterTopics, ...extendedTopics];
Topic topicById(String id) => courseTopics.firstWhere((t) => t.id == id);

class Exercise {
  const Exercise({required this.id, required this.topic, required this.category, required this.type, required this.title, required this.prompt, this.options = const [], this.answer = '', this.accepted = const [], this.tests = const [], this.hints = const [], this.solution = '', this.rubric = const [], this.filename = 'learner.py', this.required = true});
  final String id, topic, category, type, title, prompt, answer, solution, filename;
  final List<String> options, accepted, hints, rubric;
  final List<Map<String, dynamic>> tests;
  final bool required;
  Map<String, dynamic> get marking => {'id': id, 'type': type, 'answer': answer, 'accepted': accepted, 'tests': tests};
}
