  Exercise(id:"python-c0-t7-classwork-1-v1", topic:"python-c0-t7", category:"Classwork", type:"code", title:"Return a score", prompt:"Define calculate_score(base, multiplier) to return their product. Supply only the function and do not print from inside it.", tests:[{"input":[],"expected":"50","harness":"print(calculate_score(10,5))","comparison":"numeric"},{"input":[],"expected":"-6","harness":"print(calculate_score(-2,3))","comparison":"numeric"},{"input":[],"expected":"0","harness":"print(calculate_score(0,9))","comparison":"numeric"}], hints:["Check what the caller receives."], required:false, filename:"learner.py"),
