  Exercise(id:"python-c0-t7-project-4-v1", topic:"python-c0-t7", category:"Project", type:"code", title:"Functions and Variables: mock summary utility", prompt:"Define failure_percent(total, failed) returning the percentage for a positive total. Define main() to read a target label, a positive integer total, and a failed count between zero and total. Strip/lowercase the target. Output Target: NAME, Total: N, Failed: M, Failure rate: P% on four lines; P has two decimals. Call main only through the standard main guard. This is mock data; no files or network requests are required. Explain two cases in My Notes.", tests:[{"input":["  EXAMPLE.ORG ","20","3"],"expected":"Target: example.org\nTotal: 20\nFailed: 3\nFailure rate: 15.00%","harness":"import ast,math\nassert callable(globals().get('failure_percent')), 'Define failure_percent(total, failed).'\nassert math.isclose(failure_percent(4,1),25), 'Return the calculated percentage.'\nassert callable(globals().get('main')), 'Define main().'\ntree=ast.parse(_academy_source)\ndef guard(node):\n    if not isinstance(node,ast.If) or not isinstance(node.test,ast.Compare) or len(node.test.ops)!=1 or not isinstance(node.test.ops[0],ast.Eq):\n        return False\n    values=[node.test.left,*node.test.comparators]\n    return any(isinstance(v,ast.Name) and v.id=='__name__' for v in values) and any(isinstance(v,ast.Constant) and v.value=='__main__' for v in values)\nassert any(guard(n) for n in tree.body), 'Use the standard main guard.'","comparison":"normalized"},{"input":["DEMO","4","0"],"expected":"Target: demo\nTotal: 4\nFailed: 0\nFailure rate: 0.00%","harness":"import ast,math\nassert callable(globals().get('failure_percent')), 'Define failure_percent(total, failed).'\nassert math.isclose(failure_percent(4,1),25), 'Return the calculated percentage.'\nassert callable(globals().get('main')), 'Define main().'\ntree=ast.parse(_academy_source)\ndef guard(node):\n    if not isinstance(node,ast.If) or not isinstance(node.test,ast.Compare) or len(node.test.ops)!=1 or not isinstance(node.test.ops[0],ast.Eq):\n        return False\n    values=[node.test.left,*node.test.comparators]\n    return any(isinstance(v,ast.Name) and v.id=='__name__' for v in values) and any(isinstance(v,ast.Constant) and v.value=='__main__' for v in values)\nassert any(guard(n) for n in tree.body), 'Use the standard main guard.'","comparison":"normalized"},{"input":["mock","3","1"],"expected":"Target: mock\nTotal: 3\nFailed: 1\nFailure rate: 33.33%","harness":"import ast,math\nassert callable(globals().get('failure_percent')), 'Define failure_percent(total, failed).'\nassert math.isclose(failure_percent(4,1),25), 'Return the calculated percentage.'\nassert callable(globals().get('main')), 'Define main().'\ntree=ast.parse(_academy_source)\ndef guard(node):\n    if not isinstance(node,ast.If) or not isinstance(node.test,ast.Compare) or len(node.test.ops)!=1 or not isinstance(node.test.ops[0],ast.Eq):\n        return False\n    values=[node.test.left,*node.test.comparators]\n    return any(isinstance(v,ast.Name) and v.id=='__name__' for v in values) and any(isinstance(v,ast.Constant) and v.value=='__main__' for v in values)\nassert any(guard(n) for n in tree.body), 'Use the standard main guard.'","comparison":"normalized"}], hints:["Separate calculation from the input/output interface."], required:false, filename:"main.py"),
  Exercise(id:"python-c0-t7-assessment-5-v1", topic:"python-c0-t7", category:"Assessment", type:"choice", title:"Send a result", prompt:"Which keyword sends a value back to a caller?", options:["send","output","return","back"], answer:"2", solution:"return supplies the result of a function call.", required:false),
  Exercise(id:"python-c0-t7-assessment-6-v1", topic:"python-c0-t7", category:"Assessment", type:"choice", title:"Control after return", prompt:"What happens after a return is executed?", options:["The call pauses indefinitely","The current call ends and control returns to its caller","The whole interpreter always closes","The value is automatically printed"], answer:"1", solution:"Ending a call differs from printing or ending Python.", required:false),
  Exercise(id:"python-c0-t7-assessment-7-v1", topic:"python-c0-t7", category:"Assessment", type:"written", title:"Return versus print", prompt:"Explain why a calculation function that returns data can be reused more easily than one that only prints it.", hints:["Think about a caller that wants another calculation."], rubric:["Distinguishes return from display.","Explains reuse of a result.","Gives a caller use beyond direct printing."], required:false),
  Exercise(id:"python-c0-t7-assessment-8-v1", topic:"python-c0-t7", category:"Assessment", type:"written", title:"Program structure", prompt:"Explain the roles of calculation functions, main(), and the main guard in a small reporting program.", hints:["Give each part one responsibility."], rubric:["Describes calculation functions.","Describes the interface sequence.","Explains the run-versus-import role of the guard."], required:false),
];
List<Exercise> get exercises => [...starterExercises, ...extendedExercises];
List<Exercise> forTopic(String topic, String category) => exercises.where((e) => e.topic == topic && e.category == category).toList();
